def shipping_cost(weight_kg, dest_zone, expedited, member_tier):
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    if dest_zone not in ("domestic", "regional", "international"):
        raise ValueError("unknown zone")
    base = 5.0
    if weight_kg > 20:
        base += 12.0
    elif weight_kg > 5:
        base += 6.0
    if dest_zone == "regional":
        base *= 1.5
    elif dest_zone == "international":
        base *= 3.0
        if weight_kg > 20:
            base += 25.0
    if expedited:
        base *= 2 if dest_zone == "international" else 1.6
    if member_tier == "gold":
        base *= 0.8
    elif member_tier == "silver":
        base *= 0.9
    return round(base, 2)

